-- ************************************** DBT.FACT_LINEITEM
CREATE VIEW DBT.FACT_LINEITEM
(
  ORDERKEY COMMENT 'Foreign key referencing the order.',
  LINENUMBER COMMENT 'Line item number within an order.',
  PARTKEY COMMENT 'Foreign key referencing the part.',
  SUPPKEY COMMENT 'Foreign key referencing the supplier.',
  CUSTKEY COMMENT 'Foreign key referencing the customer who placed the order (via STG_ORDERS).',
  QUANTITY COMMENT 'Quantity of the item ordered.',
  EXTENDEDPRICE COMMENT 'Extended price of the item.',
  DISCOUNT COMMENT 'Discount applied to the item.',
  TAX COMMENT 'Tax applied to the item.',
  RETURNFLAG COMMENT 'Return status of the item.',
  LINESTATUS COMMENT 'Status code of the line item.',
  SHIPDATE COMMENT 'Date the item was shipped.',
  COMMITDATE COMMENT 'Date the item was committed for shipping.',
  RECEIPTDATE COMMENT 'Date the item was received.',
  SHIPINSTRUCT COMMENT 'Shipping instructions for the item.',
  SHIPMODE COMMENT 'Shipping mode for the item.',
  SUPPLIERNAME COMMENT 'Supplier name (uppercase), from DIM_SUPPLIER.',
  SUPPLIER_ADDRESS COMMENT 'Supplier address, from DIM_SUPPLIER.',
  SUPPLIER_PHONE COMMENT 'Supplier phone number (digits only), from DIM_SUPPLIER.',
  PART_NAME COMMENT 'Part name, from DIM_PART.',
  PART_KEY COMMENT 'Part key from DIM_PART (same value as PARTKEY when the part matches).',
  PART_MFGR COMMENT 'Part manufacturer, from DIM_PART.',
  PART_BRAND COMMENT 'Part brand, from DIM_PART.',
  PART_TYPE COMMENT 'Part type, from DIM_PART.',
  PART_SIZE COMMENT 'Part size, from DIM_PART.',
  PART_CONTAINER COMMENT 'Part container type, from DIM_PART.',
  PART_RETAILPRICE COMMENT 'Part retail price, from DIM_PART.',
  CUSTOMER_NAME COMMENT 'Customer name (uppercase), from DIM_CUSTOMER.',
  CUSTOMER_ADDRESS COMMENT 'Customer address, from DIM_CUSTOMER.',
  CUSTOMER_PHONE COMMENT 'Customer phone number (digits only), from DIM_CUSTOMER.',
  LOAD_TIMESTAMP COMMENT 'Timestamp indicating when this record was loaded into the model.',
  DISCOUNTED_PRICE COMMENT 'Extended price after discount: EXTENDEDPRICE * (1 - DISCOUNT).',
  SHIP_TO_RECEIPT_DAYS COMMENT 'Number of days between SHIPDATE and RECEIPTDATE.',
  ITEM_VALUE_CATEGORY COMMENT '''High Value'' when DISCOUNTED_PRICE > 1000, otherwise ''Low Value''.'
)
COMMENT = 'Line item fact table joining line items to supplier, part, and customer attributes (customer resolved through the order), with discounted price, shipping duration, and a high/low value category.'
AS
SELECT
    LI.ORDERKEY,
    LI.LINENUMBER,
    LI.PARTKEY,
    LI.SUPPKEY,
    O.CUSTKEY,
    LI.QUANTITY,
    LI.EXTENDEDPRICE,
    LI.DISCOUNT,
    LI.TAX,
    LI.RETURNFLAG,
    LI.LINESTATUS,
    LI.SHIPDATE,
    LI.COMMITDATE,
    LI.RECEIPTDATE,
    LI.SHIPINSTRUCT,
    LI.SHIPMODE,
    S.SUPPLIERNAME,
    S.ADDRESS AS SUPPLIER_ADDRESS,
    S.PHONE AS SUPPLIER_PHONE,
    P.NAME AS PART_NAME,
    P.PARTKEY AS PART_KEY,
    P.MFGR AS PART_MFGR,
    P.BRAND AS PART_BRAND,
    P.TYPE AS PART_TYPE,
    P.SIZE AS PART_SIZE,
    P.CONTAINER AS PART_CONTAINER,
    P.RETAILPRICE AS PART_RETAILPRICE,
    C.CUSTOMER_NAME AS CUSTOMER_NAME,
    C.ADDRESS AS CUSTOMER_ADDRESS,
    C.PHONE AS CUSTOMER_PHONE, 
    CURRENT_TIMESTAMP AS LOAD_TIMESTAMP,

    -- Simple Calculations
    LI.EXTENDEDPRICE * (1 - LI.DISCOUNT) AS DISCOUNTED_PRICE,  -- Calculated discounted price
    DATEDIFF('day', LI.SHIPDATE, LI.RECEIPTDATE) AS SHIP_TO_RECEIPT_DAYS,  -- Days between ship and receipt dates

    -- Conditional logic for high/low value items
    CASE
        WHEN LI.EXTENDEDPRICE * (1 - LI.DISCOUNT) > 1000 THEN 'High Value'
        ELSE 'Low Value'
    END AS ITEM_VALUE_CATEGORY   -- Categorize items as high or low value
FROM DBT.DBT.DIM_LINEITEM LI
LEFT JOIN DBT.DBT.DIM_SUPPLIER S ON LI.SUPPKEY = S.SUPPLIERKEY
LEFT JOIN DBT.DBT.DIM_PART P ON LI.PARTKEY = P.PARTKEY
LEFT JOIN DBT.DBT.STG_ORDERS O ON LI.ORDERKEY = O.ORDERKEY
LEFT JOIN DBT.DBT.DIM_CUSTOMER C ON O.CUSTKEY = C.CUSTKEY;

